// Browser-side tiny-voca engine (Route B): WASM C engine + tvoca.bin,
// no server involved. Loads the model and the kuromoji dictionary from
// static files under /model, /engine and /kuromoji-dict.

import { initPhonemizer, phonemize } from "@tiny-voca-ja/phonemizer";
// The Emscripten engine JS is generated by engine/build.sh into
// public/engine/ and staged to src/engine-dist/ by prepare-assets, so it
// can be imported as a regular module (Vite will not serve /public files
// through its module pipeline). Its .wasm stays in /public/engine/ and is
// fetched at runtime via locateFile below.
import createTvModule from "./engine-dist/tv_engine.js";

interface TvModule {
  _malloc(size: number): number;
  _free(ptr: number): void;
  _tvw_init(dataPtr: number, size: number): number;
  _tvw_synth(
    idsPtr: number,
    stressPtr: number,
    n: number,
    voice: number,
    speed: number,
    outSamplesPtr: number,
    outSaturationsPtr: number,
  ): number;
  _tvw_free(ptr: number): void;
  HEAPU8: Uint8Array;
  HEAP32: Int32Array;
  HEAPF32: Float32Array;
}

let modulePromise: Promise<TvModule> | null = null;

async function loadModule(): Promise<TvModule> {
  if (!modulePromise) {
    modulePromise = (async () => {
      const factory = createTvModule as unknown as (
        opts: Record<string, unknown>,
      ) => Promise<TvModule>;
      const mod = await factory({ locateFile: (path: string) => `/engine/${path}` });
      const bin = new Uint8Array(await (await fetch("/model/tvoca.bin")).arrayBuffer());
      const ptr = mod._malloc(bin.length);
      mod.HEAPU8.set(bin, ptr);
      const rc = mod._tvw_init(ptr, bin.length);
      mod._free(ptr);
      if (rc !== 0) throw new Error("tvoca.bin の読み込みに失敗しました");
      await initPhonemizer("/kuromoji-dict/");
      return mod;
    })();
  }
  return modulePromise;
}

export function encodeWav(samples: Float32Array, sampleRate: number): Blob {
  const buffer = new ArrayBuffer(44 + samples.length * 2);
  const view = new DataView(buffer);
  const writeStr = (offset: number, s: string) => {
    for (let i = 0; i < s.length; i++) view.setUint8(offset + i, s.charCodeAt(i));
  };
  writeStr(0, "RIFF");
  view.setUint32(4, 36 + samples.length * 2, true);
  writeStr(8, "WAVE");
  writeStr(12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeStr(36, "data");
  view.setUint32(40, samples.length * 2, true);
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]));
    view.setInt16(44 + i * 2, Math.round(s * 32767), true);
  }
  return new Blob([buffer], { type: "audio/wav" });
}

export interface SynthResult {
  blob: Blob;
  phonemes: number;
  saturations: number;
}

export async function speak(text: string, voice: number, speed: number): Promise<SynthResult> {
  const mod = await loadModule();
  const { ids, stress } = await phonemize(text);
  const n = ids.length;
  const idsPtr = mod._malloc(n * 4);
  const stressPtr = mod._malloc(n * 4);
  const outSamplesPtr = mod._malloc(4);
  const outSatPtr = mod._malloc(8);
  try {
    mod.HEAP32.set(ids, idsPtr / 4);
    mod.HEAP32.set(stress, stressPtr / 4);
    const audioPtr = mod._tvw_synth(idsPtr, stressPtr, n, voice, speed, outSamplesPtr, outSatPtr);
    const samples = mod.HEAP32[outSamplesPtr / 4];
    if (!audioPtr || samples <= 0) throw new Error(`合成に失敗しました (code ${samples})`);
    const saturations = Number(mod.HEAPF32[outSatPtr / 4]); // low word of the long is enough for a 0-check
    const wave = mod.HEAPF32.slice(audioPtr / 4, audioPtr / 4 + samples);
    mod._tvw_free(audioPtr);
    let peak = 0;
    for (const v of wave) peak = Math.max(peak, Math.abs(v));
    if (peak > 0.99) {
      const scale = 0.99 / peak;
      for (let i = 0; i < wave.length; i++) wave[i] *= scale;
    }
    return { blob: encodeWav(wave, 24000), phonemes: n, saturations };
  } finally {
    mod._free(idsPtr);
    mod._free(stressPtr);
    mod._free(outSamplesPtr);
    mod._free(outSatPtr);
  }
}
